package com.neml.badminton.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.neml.badminton.dto.CricketDtos.*; import com.neml.badminton.entity.*; import com.neml.badminton.repository.*;
import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
import java.time.Instant; import java.util.*;
@Service
public class CricketScoringService {
 private final MatchRepository matches; private final TeamRepository teams; private final PlayerRepository players;
 private final CricketConfigurationRepository configs; private final CricketMatchStateRepository states; private final CricketPlayingMemberRepository members;
 private final CricketInningsRepository innings; private final CricketDeliveryRepository deliveries; private final SquadConfirmationService squads;
 private final CompetitionService competition; private final ObjectMapper json;
 private final ConfigurationSectionService configurationSections;
 private final RosterQuotaRuleRepository quotaRules;
 public CricketScoringService(MatchRepository matches,TeamRepository teams,PlayerRepository players,CricketConfigurationRepository configs,
  CricketMatchStateRepository states,CricketPlayingMemberRepository members,CricketInningsRepository innings,CricketDeliveryRepository deliveries,
  SquadConfirmationService squads,CompetitionService competition,ObjectMapper json,ConfigurationSectionService configurationSections,RosterQuotaRuleRepository quotaRules){this.matches=matches;this.teams=teams;this.players=players;this.configs=configs;this.states=states;this.members=members;this.innings=innings;this.deliveries=deliveries;this.squads=squads;this.competition=competition;this.json=json;this.configurationSections=configurationSections;this.quotaRules=quotaRules;}
 @Transactional public void lockXi(UUID cid,UUID matchId,UUID teamId,PlayingXiRequest r,User actor){Match m=match(cid,matchId);Team team=team(cid,teamId);assertParticipant(m,team);
  if(!members.findAllByChampionshipIdAndMatchIdAndTeamId(cid,matchId,teamId).isEmpty())conflict("Playing XI is already locked"); squads.assertTeamLocked(cid,teamId);
  CricketConfiguration c=config(cid); if(r.playerIds().size()!=c.getPlayersPerSide()||new HashSet<>(r.playerIds()).size()!=r.playerIds().size())bad("Playing XI must contain exactly "+c.getPlayersPerSide()+" distinct players");
  Set<UUID> keepers=new LinkedHashSet<>();if(r.wicketkeeperId()!=null)keepers.add(r.wicketkeeperId());if(r.wicketkeeperIds()!=null)keepers.addAll(r.wicketkeeperIds());
  if(!r.playerIds().contains(r.captainId())||!r.playerIds().containsAll(keepers))bad("Captain and wicketkeepers must be members of the playing XI");
  if(keepers.size()!=c.getRequiredWicketkeepers())bad("Playing XI must contain exactly "+c.getRequiredWicketkeepers()+" wicketkeeper(s)");
  List<Player> selected=r.playerIds().stream().map(id->players.findByIdAndChampionshipId(id,cid).orElseThrow(()->notFound("Player"))).toList();
  if(selected.stream().anyMatch(p->p.getTeam()==null||!p.getTeam().getId().equals(teamId)))bad("Every playing member must belong to the selected team");
  validatePlayingSideQuotas(cid,selected);
  members.saveAll(selected.stream().map(p->CricketPlayingMember.builder().championship(m.getChampionship()).match(m).team(team).player(p).captain(p.getId().equals(r.captainId())).wicketkeeper(keepers.contains(p.getId())).lockedAt(Instant.now()).build()).toList());competition.recordResultAudit(m,actor,"CRICKET_PLAYING_SIDE_LOCKED",Map.of("teamId",teamId,"playerIds",r.playerIds(),"captainId",r.captainId(),"wicketkeeperIds",keepers));}
 @Transactional public MatchStateDto toss(UUID cid,UUID matchId,TossRequest r,User actor){Match m=lockedMatch(cid,matchId);if(states.findByMatchIdAndChampionshipId(matchId,cid).isPresent())conflict("Toss is already recorded");
  if(members.countByChampionshipIdAndMatchId(cid,matchId)!=2L*config(cid).getPlayersPerSide())conflict("Both playing XIs must be locked before the toss");
  Team winner=team(cid,r.winnerTeamId());assertParticipant(m,winner);CricketMatchState s=states.save(CricketMatchState.builder().championship(m.getChampionship()).match(m).tossWinner(winner).tossDecision(r.decision()).build());m.setStatus(MatchStatus.LIVE);matches.save(m);competition.recordResultAudit(m,actor,"CRICKET_TOSS_RECORDED",Map.of("winnerTeamId",winner.getId(),"decision",r.decision()));return dto(s);}
 @Transactional public MatchStateDto startInnings(UUID cid,UUID matchId,StartInningsRequest r,User actor){Match m=lockedMatch(cid,matchId);CricketConfiguration rules=config(cid);CricketMatchState s=states.findForUpdate(cid,matchId).orElseGet(()->{if(Boolean.TRUE.equals(rules.getTossRequired()))throw conflictEx("Record the toss first");if(members.countByChampionshipIdAndMatchId(cid,matchId)!=2L*rules.getPlayersPerSide())throw conflictEx("Both playing XIs must be locked before the innings");m.setStatus(MatchStatus.LIVE);matches.save(m);return states.save(CricketMatchState.builder().championship(m.getChampionship()).match(m).build());});
  List<CricketInnings> existing=innings.findAllByChampionshipIdAndMatchIdOrderByInningsNumber(cid,matchId);int maximum=2+2*config(cid).getMaximumSuperOvers();if(existing.size()>=maximum||existing.stream().anyMatch(i->i.getStatus()==CricketInningsStatus.LIVE))conflict("The next innings cannot start yet");if(existing.size()>=2&&(s.getResultText()==null||!s.getResultText().contains("super over required")))conflict("A super over is not currently required");
  Team batting=team(cid,r.battingTeamId());assertParticipant(m,batting);if(existing.isEmpty()&&s.getTossWinner()!=null){UUID expected="BAT".equals(s.getTossDecision())?s.getTossWinner().getId():(m.getTeamA().getId().equals(s.getTossWinner().getId())?m.getTeamB().getId():m.getTeamA().getId());if(!expected.equals(batting.getId()))bad("First innings batting team must match the recorded toss decision");}if(!existing.isEmpty()&&existing.get(existing.size()-1).getBattingTeam().getId().equals(batting.getId()))bad("Consecutive innings must use the other batting team");
  CricketInnings created=innings.save(CricketInnings.builder().championship(m.getChampionship()).match(m).battingTeam(batting).inningsNumber(existing.size()+1).startedAt(Instant.now()).build());competition.recordResultAudit(m,actor,"CRICKET_INNINGS_STARTED",Map.of("inningsId",created.getId(),"inningsNumber",created.getInningsNumber(),"battingTeamId",batting.getId()));return dto(s);}
 @Transactional public MatchStateDto delivery(UUID cid,UUID matchId,UUID inningsId,DeliveryRequest r,User actor){CricketInnings i=innings.findForUpdate(cid,inningsId).orElseThrow(()->notFound("Innings"));Optional<CricketDelivery> duplicate=deliveries.findByChampionshipIdAndIdempotencyKey(cid,r.idempotencyKey());if(duplicate.isPresent()){if(!duplicate.get().getInnings().getMatch().getId().equals(matchId))conflict("Idempotency key is already used by another match");return dto(state(cid,matchId));}if(!i.getMatch().getId().equals(matchId)||i.getStatus()!=CricketInningsStatus.LIVE)conflict("Innings is not live");
  UUID battingTeam=i.getBattingTeam().getId();UUID fieldingTeam=i.getMatch().getTeamA().getId().equals(battingTeam)?i.getMatch().getTeamB().getId():i.getMatch().getTeamA().getId();
  if(r.strikerPlayerId().equals(r.nonStrikerPlayerId()))bad("Striker and non-striker must be different players");
  if(!members.existsByChampionshipIdAndMatchIdAndTeamIdAndPlayerId(cid,matchId,battingTeam,r.strikerPlayerId())||!members.existsByChampionshipIdAndMatchIdAndTeamIdAndPlayerId(cid,matchId,battingTeam,r.nonStrikerPlayerId()))bad("Both batters must belong to the locked batting XI");
  if(!members.existsByChampionshipIdAndMatchIdAndTeamIdAndPlayerId(cid,matchId,fieldingTeam,r.bowlerPlayerId()))bad("Bowler must belong to the locked fielding XI");
  CricketConfiguration c=config(cid);if(r.byes()>0&&r.legByes()>0)bad("A delivery cannot contain both byes and leg byes");if(r.wicket()&&(r.wicketPlayerId()==null||r.dismissalType()==null||r.dismissalType().isBlank()))bad("Wicket player and dismissal type are required for a wicket");if(r.wicketPlayerId()!=null&&!members.existsByChampionshipIdAndMatchIdAndTeamIdAndPlayerId(cid,matchId,battingTeam,r.wicketPlayerId()))bad("Dismissed player must belong to the locked batting XI");boolean legal=isLegal(r.wides(),r.noBalls());int total=deliveryRuns(r.batterRuns(),r.wides()*c.getWideBallRuns(),r.noBalls()*c.getNoBallRuns(),r.byes(),r.legByes(),r.penaltyRuns());
  List<CricketDelivery> prior=deliveries.findAllByChampionshipIdAndInningsIdAndVoidedFalseOrderByDeliverySequence(cid,inningsId);boolean freeHit=c.getFreeHitEnabled()&&freeHitDue(prior);
  if(!prior.isEmpty()){CricketDelivery previous=prior.get(prior.size()-1);if(!previous.getWicket()){boolean swap=(previous.getTotalRuns()%2==1)^(previous.getLegalBall()&&i.getLegalBalls()%6==0);UUID expectedStriker=swap?previous.getNonStrikerPlayerId():previous.getStrikerPlayerId(),expectedNonStriker=swap?previous.getStrikerPlayerId():previous.getNonStrikerPlayerId();if(!expectedStriker.equals(r.strikerPlayerId())||!expectedNonStriker.equals(r.nonStrikerPlayerId()))bad("Striker and non-striker do not match the backend-calculated strike");}}
  if(freeHit&&r.wicket()&&!"RUN_OUT".equalsIgnoreCase(r.dismissalType()))bad("Only a run-out dismissal is permitted on a free hit");
  int sequence=deliveries.findTopByInningsIdOrderByDeliverySequenceDesc(inningsId).map(d->d.getDeliverySequence()+1).orElse(1);
  if(legal&&deliveries.countByChampionshipIdAndInningsIdAndBowlerPlayerIdAndLegalBallTrueAndVoidedFalse(cid,inningsId,r.bowlerPlayerId())>=c.getMaximumOversPerBowler()*6L)bad("Bowler has reached the configured limit of "+c.getMaximumOversPerBowler()+" overs");
  deliveries.save(CricketDelivery.builder().championship(i.getChampionship()).innings(i).deliverySequence(sequence).idempotencyKey(r.idempotencyKey()).strikerPlayerId(r.strikerPlayerId()).nonStrikerPlayerId(r.nonStrikerPlayerId()).bowlerPlayerId(r.bowlerPlayerId()).wicketPlayerId(r.wicketPlayerId()).batterRuns(r.batterRuns()).wides(r.wides()).noBalls(r.noBalls()).byes(r.byes()).legByes(r.legByes()).penaltyRuns(r.penaltyRuns()).wicket(r.wicket()).dismissalType(r.dismissalType()).legalBall(legal).totalRuns(total).occurredAt(Instant.now()).build());
  configurationSections.lock(cid,"SPORT_RULES",actor);
  i.setRuns(i.getRuns()+total);if(r.wicket())i.setWickets(i.getWickets()+1);if(legal)i.setLegalBalls(i.getLegalBalls()+1);CricketMatchState s=state(cid,matchId);
  boolean superOver=i.getInningsNumber()>2;int maxBalls=superOver?6:c.getOversPerInnings()*6;int maxWickets=superOver?2:c.getPlayersPerSide()-1;
  boolean chase=i.getInningsNumber()%2==0&&s.getTargetRuns()!=null&&i.getRuns()>=s.getTargetRuns();boolean exhausted=i.getLegalBalls()>=maxBalls||i.getWickets()>=maxWickets;
  if(chase||exhausted){i.setStatus(CricketInningsStatus.COMPLETED);i.setCompletedAt(Instant.now());if(i.getInningsNumber()%2==1){s.setTargetRuns(i.getRuns()+1);if(superOver)s.setSuperOverCount(s.getSuperOverCount()+1);}else finish(i.getMatch(),s,i,actor);}innings.save(i);states.save(s);updateScore(i.getMatch(),s);return dto(s);}
 @Transactional public MatchStateDto correctDelivery(UUID cid,UUID matchId,UUID inningsId,UUID deliveryId,DeliveryCorrectionRequest r,User actor){
  CricketInnings i=innings.findForUpdate(cid,inningsId).orElseThrow(()->notFound("Innings"));if(!i.getMatch().getId().equals(matchId))bad("Delivery does not belong to this match");if(!Objects.equals(i.getVersion(),r.expectedInningsVersion()))conflict("Innings version conflict: reload before correcting");
  List<CricketInnings> matchInnings=innings.findAllByChampionshipIdAndMatchIdOrderByInningsNumber(cid,matchId);if(!matchInnings.get(matchInnings.size()-1).getId().equals(inningsId))conflict("Only the current innings can be corrected");
  CricketDelivery d=deliveries.findByIdAndChampionshipId(deliveryId,cid).orElseThrow(()->notFound("Delivery"));if(!d.getInnings().getId().equals(inningsId)||Boolean.TRUE.equals(d.getVoided()))bad("Delivery is not an active delivery in this innings");
  CricketDelivery latest=deliveries.findTopByChampionshipIdAndInningsIdAndVoidedFalseOrderByDeliverySequenceDesc(cid,inningsId).orElseThrow(()->notFound("Delivery"));if(!latest.getId().equals(deliveryId))conflict("Only the latest delivery can be corrected; reverse later deliveries first");
  Map<String,Object> before=Map.of("deliveryId",d.getId(),"sequence",d.getDeliverySequence(),"runs",d.getTotalRuns(),"wicket",d.getWicket());d.setVoided(true);d.setCorrectionReason(r.reason().trim());d.setCorrectedAt(Instant.now());d.setCorrectedByUserId(actor==null?null:actor.getId());deliveries.save(d);
  rebuildCurrentInnings(i);CricketMatchState s=state(cid,matchId);s.setResultText(null);s.setTargetRuns(targetFor(matchInnings,i));s.setSuperOverCount((int)matchInnings.stream().filter(x->x.getInningsNumber()>2&&x.getInningsNumber()%2==1&&x.getStatus()==CricketInningsStatus.COMPLETED).count());states.save(s);
  Match m=i.getMatch();m.setStatus(MatchStatus.LIVE);m.setWinnerTeam(null);m.setTeamAPoints(0);m.setTeamBPoints(0);m.setResultRevision(m.getResultRevision()+1);matches.save(m);competition.recordResultAudit(m,actor,"CRICKET_DELIVERY_CORRECTED",Map.of("reason",r.reason().trim(),"before",before,"after","VOIDED"));updateScore(m,s);return dto(s);}
 @Transactional public MatchStateDto stateView(UUID cid,UUID matchId){return dto(state(cid,matchId));}
 @Transactional public MatchStateDto overrideTarget(UUID cid,UUID matchId,TargetOverrideRequest r,User actor){Match m=lockedMatch(cid,matchId);CricketConfiguration rules=config(cid);if(!Boolean.TRUE.equals(rules.getAdministrativeTargetOverrideAllowed()))conflict("Administrative target overrides are disabled by championship policy");CricketMatchState s=state(cid,matchId);List<CricketInnings> played=innings.findAllByChampionshipIdAndMatchIdOrderByInningsNumber(cid,matchId);if(played.isEmpty()||played.get(played.size()-1).getInningsNumber()%2!=0)conflict("A target can only be overridden during a chasing innings");Integer before=s.getTargetRuns();s.setTargetRuns(r.targetRuns());states.save(s);m.setResultRevision(m.getResultRevision()+1);matches.save(m);competition.recordResultAudit(m,actor,"CRICKET_TARGET_OVERRIDDEN",Map.of("before",before==null?"":before,"after",r.targetRuns(),"reason",r.reason()));updateScore(m,s);return dto(s);}
 @Transactional public MatchStateDto administrativeResult(UUID cid,UUID matchId,AdministrativeResultRequest r,User actor){Match m=lockedMatch(cid,matchId);CricketConfiguration rules=config(cid);if(!Boolean.TRUE.equals(rules.getAdministrativeResultOverrideAllowed()))conflict("Administrative result overrides are disabled by championship policy");CricketMatchState s=states.findForUpdate(cid,matchId).orElseGet(()->states.save(CricketMatchState.builder().championship(m.getChampionship()).match(m).build()));Team winner=null;if("TEAM_WIN".equals(r.outcome())){if(r.winnerTeamId()==null)bad("A winning team is required");winner=team(cid,r.winnerTeamId());assertParticipant(m,winner);}int win=configPoints(m,true),draw="NO_RESULT".equals(r.outcome())||"ABANDONED".equals(r.outcome())?competition.configuration(cid).pointsPerNoResult():configPoints(m,false);m.setWinnerTeam(winner);m.setTeamAPoints(winner==null?draw:winner.getId().equals(m.getTeamA().getId())?win:0);m.setTeamBPoints(winner==null?draw:winner.getId().equals(m.getTeamB().getId())?win:0);m.setStatus(MatchStatus.COMPLETED);m.setResultRevision(m.getResultRevision()+1);s.setResultText(r.outcome().replace('_',' ')+" (administrative)");matches.save(m);states.save(s);competition.recordResultAudit(m,actor,"CRICKET_ADMINISTRATIVE_RESULT",Map.of("outcome",r.outcome(),"reason",r.reason(),"winnerTeamId",winner==null?"":winner.getId().toString()));competition.advanceAfterCompletion(cid,matchId,actor);updateScore(m,s);return dto(s);}
 private void finish(Match m,CricketMatchState s,CricketInnings second,User actor){List<CricketInnings> played=innings.findAllByChampionshipIdAndMatchIdOrderByInningsNumber(m.getChampionship().getId(),m.getId());CricketInnings first=played.get(played.size()-2);Team winner=null;
  if(second.getRuns()>first.getRuns()){winner=second.getBattingTeam();s.setResultText(second.getInningsNumber()>2?"Won after super over":"Won by "+(config(m.getChampionship().getId()).getPlayersPerSide()-1-second.getWickets())+" wickets");}
  else if(first.getRuns()>second.getRuns()){winner=first.getBattingTeam();s.setResultText(second.getInningsNumber()>2?"Won after super over":"Won by "+(first.getRuns()-second.getRuns())+" runs");}else{CricketConfiguration rules=config(m.getChampionship().getId());if("SUPER_OVER".equals(rules.getTiePolicy())&&s.getSuperOverCount()<rules.getMaximumSuperOvers()){s.setResultText("Match tied - super over required");s.setTargetRuns(null);return;}if("ADMINISTRATIVE".equals(rules.getTiePolicy())){s.setResultText("Match tied - administrative decision required");return;}s.setResultText("Match tied");}
  m.setWinnerTeam(winner);m.setStatus(MatchStatus.COMPLETED);m.setResultRevision(m.getResultRevision()+1);int win=configPoints(m,true),tie=configPoints(m,false);m.setTeamAPoints(winner==null?tie:winner.getId().equals(m.getTeamA().getId())?win:0);m.setTeamBPoints(winner==null?tie:winner.getId().equals(m.getTeamB().getId())?win:0);matches.save(m);competition.advanceAfterCompletion(m.getChampionship().getId(),m.getId(),actor);}
 private int configPoints(Match m,boolean win){var c=competition.configuration(m.getChampionship().getId());return win?c.pointsPerWin():c.pointsPerTie();}
 private void updateScore(Match m,CricketMatchState s){try{m.setScoreData(json.writeValueAsString(dto(s)));matches.save(m);}catch(Exception e){throw new IllegalStateException(e);}}
  private MatchStateDto dto(CricketMatchState s){List<CricketInnings> list=innings.findAllByChampionshipIdAndMatchIdOrderByInningsNumber(s.getChampionship().getId(),s.getMatch().getId());return new MatchStateDto(s.getMatch().getId(),s.getTossWinner()==null?null:s.getTossWinner().getId(),s.getTossDecision(),s.getResultText(),list.stream().map(i->inningsDto(s,i)).toList());}
 private InningsDto inningsDto(CricketMatchState s,CricketInnings i){List<CricketDelivery> ledger=deliveries.findAllByChampionshipIdAndInningsIdAndVoidedFalseOrderByDeliverySequence(s.getChampionship().getId(),i.getId());Map<UUID,int[]> bat=new LinkedHashMap<>(),bowl=new LinkedHashMap<>();Set<UUID> out=new HashSet<>();for(CricketDelivery d:ledger){int[] b=bat.computeIfAbsent(d.getStrikerPlayerId(),x->new int[4]);b[0]+=d.getBatterRuns();if(d.getWides()==0)b[1]++;if(d.getBatterRuns()==4)b[2]++;if(d.getBatterRuns()==6)b[3]++;if(d.getWicketPlayerId()!=null)out.add(d.getWicketPlayerId());int[] o=bowl.computeIfAbsent(d.getBowlerPlayerId(),x->new int[3]);o[0]+=d.getTotalRuns()-d.getByes()-d.getLegByes();if(d.getLegalBall())o[2]++;if(d.getWicket()&&!Set.of("RUN_OUT","RETIRED_HURT","OBSTRUCTING_THE_FIELD").contains(String.valueOf(d.getDismissalType()).toUpperCase(Locale.ROOT)))o[1]++;}List<BatterStatsDto> batting=bat.entrySet().stream().map(e->new BatterStatsDto(e.getKey(),e.getValue()[0],e.getValue()[1],e.getValue()[2],e.getValue()[3],out.contains(e.getKey()))).toList();List<BowlerStatsDto> bowling=bowl.entrySet().stream().map(e->new BowlerStatsDto(e.getKey(),e.getValue()[0],e.getValue()[1],e.getValue()[2],formatOvers(e.getValue()[2]))).toList();Integer target=i.getInningsNumber()%2==0?s.getTargetRuns():null;Double required=null;if(target!=null&&i.getStatus()==CricketInningsStatus.LIVE){int max=i.getInningsNumber()>2?6:config(s.getChampionship().getId()).getOversPerInnings()*6,balls=Math.max(1,max-i.getLegalBalls());required=Math.max(0,target-i.getRuns())*6.0/balls;}List<DeliveryDto> deliveryDtos=ledger.stream().map(d->new DeliveryDto(d.getId(),d.getDeliverySequence(),d.getStrikerPlayerId(),d.getNonStrikerPlayerId(),d.getBowlerPlayerId(),d.getBatterRuns(),d.getWides(),d.getNoBalls(),d.getByes(),d.getLegByes(),d.getPenaltyRuns(),d.getWicket(),d.getDismissalType(),d.getLegalBall(),d.getTotalRuns())).toList();UUID nextStriker=null,nextNonStriker=null;if(!ledger.isEmpty()){CricketDelivery last=ledger.get(ledger.size()-1);if(!last.getWicket()){boolean swap=(last.getTotalRuns()%2==1)^(last.getLegalBall()&&i.getLegalBalls()%6==0);nextStriker=swap?last.getNonStrikerPlayerId():last.getStrikerPlayerId();nextNonStriker=swap?last.getStrikerPlayerId():last.getNonStrikerPlayerId();}}return new InningsDto(i.getId(),i.getVersion(),i.getInningsNumber(),i.getBattingTeam().getId(),i.getRuns(),i.getWickets(),i.getLegalBalls(),formatOvers(i.getLegalBalls()),i.getStatus().name(),target,required,nextStriker,nextNonStriker,batting,bowling,deliveryDtos);}
 static boolean freeHitDue(List<CricketDelivery> deliveries){for(int x=deliveries.size()-1;x>=0;x--){CricketDelivery d=deliveries.get(x);if(d.getNoBalls()>0)return true;if(d.getLegalBall())return false;}return false;}
 private void rebuildCurrentInnings(CricketInnings i){List<CricketDelivery> ledger=deliveries.findAllByChampionshipIdAndInningsIdAndVoidedFalseOrderByDeliverySequence(i.getChampionship().getId(),i.getId());i.setRuns(ledger.stream().mapToInt(CricketDelivery::getTotalRuns).sum());i.setWickets((int)ledger.stream().filter(CricketDelivery::getWicket).count());i.setLegalBalls((int)ledger.stream().filter(CricketDelivery::getLegalBall).count());i.setStatus(CricketInningsStatus.LIVE);i.setCompletedAt(null);innings.save(i);}
 private Integer targetFor(List<CricketInnings> all,CricketInnings current){if(current.getInningsNumber()%2==0){CricketInnings previous=all.get(all.indexOf(current)-1);return previous.getRuns()+1;}return null;}
 private void validatePlayingSideQuotas(UUID cid,List<Player> selected){List<String> errors=new ArrayList<>();for(RosterQuotaRule q:quotaRules.findAllByChampionshipIdAndEnabledTrue(cid)){if(!"PLAYING_SIDE".equalsIgnoreCase(q.getAppliesTo()))continue;long count=switch(q.getCategoryType().toUpperCase(Locale.ROOT)){case "GENDER"->selected.stream().filter(p->p.getGender().name().equalsIgnoreCase(q.getCategoryValue())).count();case "SKILL_LEVEL","PLAYER_CATEGORY"->selected.stream().filter(p->p.getSkillLevel()!=null&&p.getSkillLevel().equalsIgnoreCase(q.getCategoryValue())).count();default->0;};if((q.getMinimumCount()!=null&&count<q.getMinimumCount())||(q.getMaximumCount()!=null&&count>q.getMaximumCount()))errors.add(q.getValidationMessage()==null||q.getValidationMessage().isBlank()?q.getRuleCode()+" playing-side quota is not satisfied":q.getValidationMessage());}if(!errors.isEmpty())bad(String.join("; ",errors));}
 static boolean isLegal(int wides,int noBalls){return wides==0&&noBalls==0;}
 static int deliveryRuns(int batter,int wides,int noBalls,int byes,int legByes,int penalties){return batter+wides+noBalls+byes+legByes+penalties;}
 static String formatOvers(int legalBalls){return legalBalls/6+"."+legalBalls%6;}
 private CricketMatchState state(UUID cid,UUID mid){return states.findForUpdate(cid,mid).orElseThrow(()->notFound("Cricket match state"));} private CricketConfiguration config(UUID cid){return configs.findFirstByChampionshipIdOrderByConfigurationVersionDesc(cid).orElseThrow(()->notFound("Cricket configuration"));}
 private Match match(UUID cid,UUID id){return matches.findByIdAndChampionshipId(id,cid).orElseThrow(()->notFound("Match"));}private Match lockedMatch(UUID cid,UUID id){return matches.findByIdAndChampionshipIdForUpdate(id,cid).orElseThrow(()->notFound("Match"));}private Team team(UUID cid,UUID id){return teams.findByIdAndChampionshipId(id,cid).orElseThrow(()->notFound("Team"));}
 private void assertParticipant(Match m,Team t){if(!m.getTeamA().getId().equals(t.getId())&&!m.getTeamB().getId().equals(t.getId()))bad("Team does not participate in this match");}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw conflictEx(m);}private ResponseStatusException conflictEx(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m+" not found");}
}
